const lessons=[{"sentences":[{"speaker":"A","text":"Good morning and welcome to the community arts centre reception desk.","position":1,"audioStartSeconds":0,"audioEndSeconds":4.438},{"speaker":"B","text":"Good morning because I want to book a place on the beginner painting course.","position":2,"audioStartSeconds":4.638,"audioEndSeconds":9.035791666666666},{"speaker":"A","text":"That is a very popular option and we only have three spots remaining this term.","position":3,"audioStartSeconds":9.235791666666668,"audioEndSeconds":14.081916666666666},{"speaker":"B","text":"That is wonderful news although I wondered about the fee per person.","position":4,"audioStartSeconds":14.281916666666667,"audioEndSeconds":18.573916666666666},{"speaker":"A","text":"The standard fee per person is eighty pounds for the whole six week block.","position":5,"audioStartSeconds":18.77391666666667,"audioEndSeconds":23.425958333333334},{"speaker":"B","text":"Should I pay seventy pounds because I am a student here.","position":6,"audioStartSeconds":23.625958333333333,"audioEndSeconds":27.350166666666667},{"speaker":"A","text":"Actually student cards do not apply to this specific weekend hobby workshop.","position":7,"audioStartSeconds":27.550166666666666,"audioEndSeconds":32.70483333333333},{"speaker":"B","text":"That makes sense and I will bring my own brushes and paints.","position":8,"audioStartSeconds":32.904833333333336,"audioEndSeconds":36.873916666666666},{"speaker":"A","text":"You must buy a canvas beforehand since basic materials are not provided.","position":9,"audioStartSeconds":37.07391666666667,"audioEndSeconds":42.11258333333333},{"speaker":"B","text":"Who will teach our group when the classes start next Saturday.","position":10,"audioStartSeconds":42.312583333333336,"audioEndSeconds":46.29454166666667},{"speaker":"A","text":"Your main tutor will be Mr Harrison who joined our staff last autumn.","position":11,"audioStartSeconds":46.49454166666667,"audioEndSeconds":51.06925},{"speaker":"B","text":"Where will we meet because the main hall is usually very busy.","position":12,"audioStartSeconds":51.26925,"audioEndSeconds":55.12233333333333},{"speaker":"A","text":"We always use room twelve on the ground floor for painting.","position":13,"audioStartSeconds":55.32233333333333,"audioEndSeconds":58.995041666666665},{"speaker":"B","text":"I can pay by credit card right now before I leave.","position":14,"audioStartSeconds":59.19504166666667,"audioEndSeconds":63.023208333333336},{"speaker":"A","text":"Please sign this receipt and your booking is fully confirmed.","position":15,"audioStartSeconds":63.22320833333333,"audioEndSeconds":67.20645833333333}],"questions":[{"prompt":"Course name: ______ painting course","answer":"beginner","evidenceSentence":2,"evidence":"beginner painting course","explanation":"Người nói B cho biết muốn đăng ký lớp học vẽ tranh dành cho người mới bắt đầu."},{"prompt":"Fee per person: ______ pounds","answer":"eighty","evidenceSentence":5,"evidence":"eighty pounds","explanation":"Nhân viên xác nhận mức phí tiêu chuẩn là tám mươi bảng Anh cho toàn bộ khóa học."},{"prompt":"Required extra supply: ______","answer":"canvas","evidenceSentence":9,"evidence":"a canvas","explanation":"Nhân viên lưu ý học viên phải mua sẵn một tấm vải bạt vì trung tâm không cung cấp."},{"prompt":"Tutor name: Mr ______","answer":"Harrison","evidenceSentence":11,"evidence":"Mr Harrison","explanation":"Giáo viên hướng dẫn chính của lớp học này sẽ là ông Harrison."},{"prompt":"Room location: room ______","answer":"twelve","evidenceSentence":13,"evidence":"room twelve","explanation":"Các lớp học vẽ được tổ chức tại phòng số mười hai ở tầng trệt."},{"prompt":"Payment method: ______ card","answer":"credit","evidenceSentence":14,"evidence":"credit card","explanation":"Khách hàng đề nghị thanh toán bằng thẻ tín dụng ngay tại thời điểm đặt chỗ."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
